// ---- ../coding/evidence.js ----
// Turns one work session's raw events into a compact evidence package for the
// AI: what changed in which files (manual vs AI-assisted), commands and their
// results, tests, git, agent conversation, app/idle time and browser research.
// Every item gets an id (E1, E2, …) so the AI's claims can cite evidence.

const MAX_ITEM_TEXT = 400;
const MAX_FILE_DIFF = 1500;
const MAX_TOTAL_DIFF = 8000;
const AI_EDIT_WINDOW_MS = 5000;
const TEST_COMMAND = /\b(test|tests|jest|vitest|mocha|pytest|cargo test|go test|npm t\b|phpunit|rspec|dotnet test|gradle test|mvn test)\b/i;

function clipText(value, max) {
    const s = String(value == null ? "" : value).replace(/\s+/g, " ").trim();
    return s.length > max ? s.slice(0, max - 1) + "…" : s;
}

function ms(ts) {
    return new Date(ts).getTime();
}

function localTime(ts, timeZone, withDate) {
    const s = new Date(ts).toLocaleString("sv-SE", { timeZone, hour12: false });
    return withDate ? s.slice(0, 16) : s.slice(11, 16);
}

function sameFile(a, b) {
    if (!a || !b) return false;
    const x = String(a).replace(/\\/g, "/").toLowerCase();
    const y = String(b).replace(/\\/g, "/").toLowerCase();
    return x === y || x.endsWith("/" + y) || y.endsWith("/" + x);
}

function appTime(context, startMs, endMs) {
    const minutes = {};
    let switches = 0;
    let idleSeconds = 0;
    let previousCategory = null;

    const focus = (context || []).filter(e => e.type === "window_focus").sort((a, b) => ms(a.ts) - ms(b.ts));
    focus.forEach((e, i) => {
        const from = Math.max(ms(e.ts), startMs);
        const next = focus[i + 1] ? ms(focus[i + 1].ts) : endMs;
        const to = Math.min(next, endMs, ms(e.ts) + 15 * 60000);
        const category = (e.data && e.data.category) || "other";
        if (to > from) minutes[category] = (minutes[category] || 0) + (to - from) / 60000;
        if (previousCategory && previousCategory !== category) switches++;
        previousCategory = category;
    });

    for (const e of context || []) {
        if (e.type === "idle_end" && e.data && e.data.idleSeconds) idleSeconds += e.data.idleSeconds;
    }

    const rounded = {};
    for (const [k, v] of Object.entries(minutes)) rounded[k] = Math.round(v);
    return { minutesByCategory: rounded, contextSwitches: switches, idleMinutes: Math.round(idleSeconds / 60) };
}

function isPassing(cmd) {
    if (cmd.tests) return cmd.tests.failed === 0 && cmd.tests.passed > 0;
    return cmd.exitCode === 0 && TEST_COMMAND.test(cmd.command || "");
}

function isFailingTest(cmd) {
    if (cmd.tests) return cmd.tests.failed > 0;
    return typeof cmd.exitCode === "number" && cmd.exitCode !== 0 && TEST_COMMAND.test(cmd.command || "");
}

// row: claimed session from "Claim Sessions"; options: { sendDiffs, timezone }
function buildEvidence(row, options) {
    const timeZone = options.timezone || "UTC";
    const events = [...(row.events || [])].sort((a, b) => ms(a.ts) - ms(b.ts));
    const startMs = ms(row.started_at);
    const endMs = ms(row.last_event_at);
    const items = [];
    const add = (kind, text, detail) => {
        const item = { id: "E" + (items.length + 1), kind, text: clipText(text, MAX_ITEM_TEXT) };
        if (detail) item.detail = detail;
        items.push(item);
        return item;
    };

    // ---- files -----------------------------------------------------------
    const agentEdits = events.filter(e => e.type === "agent_file_edit");
    const files = new Map();
    const fileEntry = (file, language) => {
        if (!files.has(file)) {
            files.set(file, { file, language: language || null, manual: { bursts: 0, added: 0, removed: 0 }, ai: { edits: 0, added: 0, removed: 0 }, diffs: [] });
        }
        const f = files.get(file);
        if (language && !f.language) f.language = language;
        return f;
    };

    for (const e of events) {
        const d = e.data || {};
        if (e.type === "edit_summary" && d.file) {
            const f = fileEntry(d.file, d.language);
            const from = ms(d.firstChangeAt || e.ts) - AI_EDIT_WINDOW_MS;
            const to = ms(d.lastChangeAt || e.ts) + AI_EDIT_WINDOW_MS;
            const byAgent = agentEdits.some(a => sameFile(a.data && a.data.file, d.file) && ms(a.ts) >= from && ms(a.ts) <= to);
            if (!byAgent) {
                f.manual.bursts++;
                f.manual.added += d.linesAdded || 0;
                f.manual.removed += d.linesRemoved || 0;
            }
            if (d.diff) f.diffs.push((byAgent ? "[AI-assisted]\n" : "") + d.diff);
        } else if (e.type === "agent_file_edit" && d.file) {
            const f = fileEntry(d.file);
            f.ai.edits++;
            f.ai.added += d.linesAdded || 0;
            f.ai.removed += d.linesRemoved || 0;
            if (d.excerpt && !f.diffs.length) f.diffs.push("[AI edit excerpt]\n" + d.excerpt);
        }
    }

    let diffBudget = options.sendDiffs ? MAX_TOTAL_DIFF : 0;
    for (const f of files.values()) {
        const parts = [];
        if (f.manual.bursts) parts.push(`manual +${f.manual.added} −${f.manual.removed} in ${f.manual.bursts} edit burst(s)`);
        if (f.ai.edits) parts.push(`AI agent +${f.ai.added} −${f.ai.removed} in ${f.ai.edits} edit(s)`);
        if (!parts.length) parts.push("AI-assisted edits");

        let detail;
        if (diffBudget > 0 && f.diffs.length) {
            const diff = f.diffs.join("\n…\n");
            detail = diff.slice(0, Math.min(MAX_FILE_DIFF, diffBudget));
            diffBudget -= detail.length;
        }
        add("file_change", `${f.file}${f.language ? " (" + f.language + ")" : ""}: ${parts.join("; ")}`, detail);
    }

    // ---- file operations --------------------------------------------------
    const created = new Set();
    const deleted = new Set();
    for (const e of events) {
        const d = e.data || {};
        if (e.type === "file_changes") {
            (d.created || []).forEach(f => created.add(f));
            (d.deleted || []).forEach(f => deleted.add(f));
        } else if (e.type === "file_renamed") {
            add("file_op", `Renamed ${d.from} → ${d.to}`);
        }
    }
    if (created.size) add("file_op", `Created: ${[...created].slice(0, 15).join(", ")}${created.size > 15 ? ` (+${created.size - 15} more)` : ""}`);
    if (deleted.size) add("file_op", `Deleted: ${[...deleted].slice(0, 15).join(", ")}${deleted.size > 15 ? ` (+${deleted.size - 15} more)` : ""}`);

    // ---- files looked at but not changed ----------------------------------
    const viewed = [...new Set(events.filter(e => e.type === "editor_focus").map(e => e.data && e.data.file).filter(Boolean))]
        .filter(f => !files.has(f));
    if (viewed.length) add("viewed", `Opened without changing: ${viewed.slice(0, 15).join(", ")}`);

    // ---- commands and tests -----------------------------------------------
    const commands = events
        .filter(e => e.type === "terminal_command" || e.type === "agent_shell")
        .map(e => ({ ...(e.data || {}), by: e.type === "agent_shell" ? "AI agent" : "user", ts: e.ts }));

    for (const c of commands.slice(-30)) {
        const result = [];
        if (typeof c.exitCode === "number") result.push(`exit ${c.exitCode}`);
        if (c.tests) result.push(`tests ${c.tests.passed} passed / ${c.tests.failed} failed`);
        const errors = (c.errorLines || []).slice(0, 4);
        add(
            c.tests || TEST_COMMAND.test(c.command || "") ? "test_run" : "command",
            `[${c.by}, ${localTime(c.ts, timeZone)}] ${c.command}${result.length ? " → " + result.join(", ") : ""}${errors.length ? " | errors: " + errors.join(" / ") : ""}`
        );
    }

    // ---- git --------------------------------------------------------------
    const branches = events.filter(e => e.type === "git_state" && e.data && e.data.branch);
    if (branches.length) add("git", `Branch: ${branches[branches.length - 1].data.branch}`);
    const commits = events.filter(e => e.type === "git_commit");
    for (const c of commits) add("commit", `Commit ${c.data.hash} on ${c.data.branch || "?"}: "${c.data.message || ""}"`);

    // ---- AI agent conversation --------------------------------------------
    for (const e of events.filter(e => e.type === "agent_prompt").slice(-10)) {
        add("agent_prompt", `User asked the AI agent: "${clipText(e.data.prompt, 350)}"`);
    }
    for (const e of events.filter(e => e.type === "agent_response").slice(-5)) {
        add("agent_response", `AI agent replied: "${clipText(e.data.text, 300)}"`);
    }
    for (const e of events.filter(e => e.type === "agent_tool_failure").slice(-5)) {
        add("agent_error", `AI agent tool ${e.data.tool || ""} failed: ${e.data.error || ""}`);
    }
    const stops = events.filter(e => e.type === "agent_stop");
    if (stops.length) add("agent_stop", `AI agent run finished (${stops[stops.length - 1].data.status || "unknown status"})`);

    // ---- browser research during the session ------------------------------
    for (const r of (row.research || []).slice(-8)) {
        add("research", `Browser ${r.website || ""} at ${localTime(r.start, timeZone)}: ${r.summary}`);
    }

    // ---- facts used to check the AI's claims ------------------------------
    const lastAgentEdit = agentEdits.length ? ms(agentEdits[agentEdits.length - 1].ts) : null;
    const facts = {
        filesChanged: [...files.keys()],
        hasPassingTest: commands.some(isPassing),
        hasFailingTest: commands.some(isFailingTest),
        lastTestPassed: (() => {
            const tests = commands.filter(c => c.tests || TEST_COMMAND.test(c.command || ""));
            return tests.length ? isPassing(tests[tests.length - 1]) : null;
        })(),
        hasCommit: commits.length > 0,
        hasAgentStopAfterEdits: lastAgentEdit !== null && stops.some(s => ms(s.ts) > lastAgentEdit && /complete/i.test(s.data.status || "")),
        eventCount: events.length
    };

    const context = appTime(row.context, startMs, endMs);

    const payload = {
        project: { name: row.project_name, root: row.project_root },
        session: {
            kind: row.final ? "ended (user inactive)" : "still in progress (interim update)",
            start: localTime(row.started_at, timeZone, true),
            end: localTime(row.last_event_at, timeZone, true),
            minutes: Math.round((endMs - startMs) / 60000)
        },
        appTime: context,
        previousSummaryOfThisTask: row.current_memory || null,
        otherOpenTasksInThisProject: (row.open_tasks || []).map(t => ({ id: t.id, title: t.title, summary: t.summary, status: t.status })),
        evidence: items
    };

    return {
        items,
        facts,
        appTime: context,
        payload,
        processedUntil: events.length ? new Date(ms(events[events.length - 1].ts)).toISOString() : row.last_event_at
    };
}

// ---- ../coding/summary.js ----
// Prompt for the coding-task summary, and validation of the AI's reply.
// The validator enforces the "facts vs inferences" rules instead of trusting
// the model: claims without evidence become inferences, and "completed" needs
// proof (passing tests, a commit, or a finished agent run after its edits).

const CODING_MAX_ATTEMPTS = 3;
const STATUSES = ["in_progress", "blocked", "completed", "unknown"];

const CODING_SYSTEM_PROMPT = `You maintain the long-term memory of a developer's personal AI assistant.

You receive one work session in one project: time range, time spent per application, and numbered evidence items (E1, E2, …) captured from the editor, terminal, git, the Cursor AI agent and the browser. You may also receive the previous summary of the same task and other open tasks in the project.

Infer what the developer is actually working on by reading the evidence together (e.g. a controller, service, schema and form changed together → one feature). Then write a cumulative summary of the task: if a previous summary is given, update it with the new evidence instead of starting over.

Rules:
- observedChanges are facts directly shown by evidence. Every one must cite evidence ids.
- inferences are your interpretations (purpose of a change, likely feature, likely cause of an error). Give each a confidence 0.0–1.0 and cite the evidence it is based on.
- Do not say something is complete just because files were edited. Use "completed" only when evidence shows passing tests, a commit, or a finished AI agent run after the edits. Failing tests or unresolved errors mean "blocked" or "in_progress".
- Record errors, failing tests and failed attempts as blockers if they were not resolved later in the session.
- nextSteps are the most likely next actions, based on blockers and unfinished work.
- If this session continues one of the other open tasks listed, set continuesMemoryId to its id.
- If nothing meaningful happened (only opening files, no changes or commands), return {"shouldStore": false}.
- Never include secrets, passwords or tokens.

Reply with JSON only:
{
  "shouldStore": true,
  "taskKey": "short-kebab-case-name-of-the-task",
  "title": "short task title",
  "summary": "2–3 sentences: what the developer is doing and where it stands",
  "objective": "the current objective",
  "status": "in_progress" | "blocked" | "completed" | "unknown",
  "progress": "what is done so far",
  "files": ["paths involved"],
  "observedChanges": [{"text": "...", "evidence": ["E1"]}],
  "inferences": [{"text": "...", "confidence": 0.7, "evidence": ["E2"]}],
  "decisions": ["technical decisions or dependencies"],
  "blockers": ["unresolved errors or failing tests"],
  "tests": [{"command": "...", "result": "passed | failed | unknown"}],
  "nextSteps": ["..."],
  "confidence": 0.0,
  "importance": 0.0,
  "continuesMemoryId": null
}`;

function buildCodingRequest(payload, model) {
    return {
        model,
        temperature: 0.2,
        messages: [
            { role: "system", content: CODING_SYSTEM_PROMPT },
            { role: "user", content: JSON.stringify(payload, null, 1) }
        ]
    };
}

function asStrings(value, max = 20, maxLen = 300) {
    return Array.isArray(value)
        ? value.filter(v => typeof v === "string" && v.trim()).slice(0, max).map(v => v.trim().slice(0, maxLen))
        : [];
}

function clamp01(value, fallback) {
    const n = Number(value);
    return isFinite(n) ? Math.min(1, Math.max(0, n)) : fallback;
}

// ctx: { attempts, evidenceIds: [], facts, currentMemoryId, openTaskIds: [] }
function parseCodingSummary(response, ctx) {
    const failure = error => ({ action: (ctx.attempts || 0) >= CODING_MAX_ATTEMPTS ? "drop" : "retry", error });

    if (!response || response.error || !Array.isArray(response.choices)) {
        return failure(response && response.error ? (response.error.message || JSON.stringify(response.error)) : "no choices in response");
    }

    let content = response.choices[0] && response.choices[0].message ? response.choices[0].message.content : "";
    if (typeof content !== "string") content = JSON.stringify(content || "");
    const start = content.indexOf("{");
    const end = content.lastIndexOf("}");
    if (start < 0 || end < start) return failure("reply is not JSON");

    let r;
    try {
        r = JSON.parse(content.slice(start, end + 1));
    } catch (err) {
        return failure("invalid JSON: " + err.message);
    }

    if (r.shouldStore !== true) return { action: "discard" };
    if (typeof r.summary !== "string" || !r.summary.trim()) return failure("summary missing");

    const known = new Set(ctx.evidenceIds || []);
    const cite = list => (Array.isArray(list) ? list.filter(id => known.has(id)) : []);

    // Facts must cite real evidence; anything else is an inference.
    const observedChanges = [];
    const inferences = [];
    for (const c of Array.isArray(r.observedChanges) ? r.observedChanges : []) {
        if (!c || typeof c.text !== "string") continue;
        const evidence = cite(c.evidence);
        if (evidence.length) observedChanges.push({ text: c.text.slice(0, 300), evidence });
        else inferences.push({ text: c.text.slice(0, 300), confidence: 0.5, evidence: [], note: "no supporting evidence cited" });
    }
    for (const c of Array.isArray(r.inferences) ? r.inferences : []) {
        if (!c || typeof c.text !== "string") continue;
        inferences.push({ text: c.text.slice(0, 300), confidence: clamp01(c.confidence, 0.5), evidence: cite(c.evidence) });
    }

    let status = STATUSES.includes(r.status) ? r.status : "unknown";
    const facts = ctx.facts || {};
    if (status === "completed" && !(facts.hasPassingTest && facts.lastTestPassed !== false) && !facts.hasCommit && !facts.hasAgentStopAfterEdits) {
        status = "in_progress";
        inferences.push({ text: "The task may be complete, but no passing tests, commit or finished agent run confirms it.", confidence: 0.4, evidence: [] });
    }
    if (status === "completed" && facts.lastTestPassed === false) {
        status = "blocked";
    }

    const blockers = asStrings(r.blockers, 10);
    const nextSteps = asStrings(r.nextSteps, 10);
    const openTaskIds = (ctx.openTaskIds || []).map(Number);
    const continues = Number(r.continuesMemoryId);
    const continuesValid = openTaskIds.includes(continues) ? continues : null;

    const targetMemoryId = ctx.currentMemoryId || continuesValid || null;
    const relatedMemoryId = ctx.currentMemoryId && continuesValid && continuesValid !== ctx.currentMemoryId ? continuesValid : null;

    const files = [...new Set([...asStrings(r.files, 50), ...(facts.filesChanged || [])])].slice(0, 50);

    let pendingTask = null;
    if (status !== "completed") {
        if (blockers.length) pendingTask = `Blocked: ${blockers[0]}${nextSteps.length ? ` — next: ${nextSteps[0]}` : ""}`;
        else if (nextSteps.length) pendingTask = nextSteps.join("; ").slice(0, 500);
    }

    return {
        action: "store",
        memory: {
            title: String(r.title || r.taskKey || "Coding task").slice(0, 200),
            taskKey: String(r.taskKey || "").toLowerCase().replace(/[^a-z0-9-]+/g, "-").replace(/^-|-$/g, "").slice(0, 80) || null,
            summary: r.summary.trim().slice(0, 1500),
            objective: typeof r.objective === "string" ? r.objective.slice(0, 500) : null,
            status,
            progress: typeof r.progress === "string" ? r.progress.slice(0, 1000) : null,
            files,
            observedChanges,
            inferences,
            decisions: asStrings(r.decisions, 10),
            blockers,
            tests: Array.isArray(r.tests)
                ? r.tests.filter(t => t && typeof t.command === "string").slice(0, 10)
                    .map(t => ({ command: t.command.slice(0, 200), result: ["passed", "failed"].includes(t.result) ? t.result : "unknown" }))
                : [],
            nextSteps,
            confidence: clamp01(r.confidence, 0.5),
            importance: clamp01(r.importance, 0.6),
            pendingTask,
            targetMemoryId,
            relatedMemoryId
        }
    };
}


// Input: claimed work sessions from "Claim Sessions".
const config = $('Config').first().json;

return $input.all().map(item => {
    const row = item.json;
    const built = buildEvidence(row, {
        sendDiffs: config.sendDiffs !== false && config.sendDiffs !== "false",
        timezone: config.timezone
    });

    return {
        json: {
            sessionId: row.session_id,
            attempts: row.attempts,
            final: !!row.final,
            projectRoot: row.project_root,
            projectName: row.project_name,
            startedAt: new Date(row.started_at).toISOString(),
            endedAt: new Date(row.last_event_at).toISOString(),
            processedUntil: built.processedUntil,
            currentMemoryId: row.memory_id ? Number(row.memory_id) : null,
            openTaskIds: (row.open_tasks || []).map(t => Number(t.id)),
            evidenceIds: built.items.map(i => i.id),
            evidenceItems: built.items.map(i => ({ id: i.id, kind: i.kind, text: i.text })),
            facts: built.facts,
            appTime: built.appTime,
            requestBody: buildCodingRequest(built.payload, config.model)
        }
    };
});

